def compute(vars):
    leased = vars["v1"]
    total = vars["v2"]
    if total == 0:
        return None

    proportion = leased / total
    percentage = proportion * 100

    return {
        "value": percentage,
        "trace": {
            "leased_facilities": leased,
            "total_facilities": total,
            "proportion": proportion,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
